function FallbackDoodle() {
  return (
    <svg viewBox="0 0 220 80" fill="none">
      <path
        d="M4 62 C 30 62, 34 14, 58 14 S 88 62, 112 62 S 146 14, 170 14 S 204 48, 216 30"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

/** Draws the doodle next to an interest as one continuous line, on click. */
export default function InterestDoodle({ name }: { name: string }) {
  const ref = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;

    const svg = el.querySelector("svg");
    if (svg) {
      // Whatever canvas Canva exported, re-frame the viewBox tightly around
      // the actual drawn content instead of the (usually much larger, mostly
      // empty) original artboard — this is what makes it fit regardless of
      // how each individual export was sized.
      try {
        const bbox = (svg as unknown as SVGSVGElement).getBBox();
        const padding = Math.max(bbox.width, bbox.height) * 0.1;
        svg.setAttribute(
          "viewBox",
          `${bbox.x - padding} ${bbox.y - padding} ${bbox.width + padding * 2} ${bbox.height + padding * 2}`
        );
      } catch {
        // getBBox can throw if the SVG has no renderable content yet — safe to skip
      }
      // Let CSS own the rendered size, regardless of whatever width/height
      // the export baked in
      svg.removeAttribute("width");
      svg.removeAttribute("height");
    }

    const ctx = gsap.context(() => {
      const targets = "path, circle, polyline, line, rect, ellipse";
      gsap
        .timeline({ defaults: { duration: 1.6, ease: "power1.inOut" } })
        .set(el, { opacity: 1 })
        .from(targets, { drawSVG: "0% 0%" }); // draws in and stays — no follow-up step erasing it
    }, el);
    return () => ctx.revert();
  }, [name]);

  return (
    <div key={name} ref={ref} className="interest-doodle w-40 text-warm opacity-0" aria-hidden>
      {DOODLES[name] ?? <FallbackDoodle />}
    </div>
  );
}